buggy.described_examples:
import itertools
import numpy as np

# Setup: create exog as described
x = 1e3 * np.arange(1.0, 41.0) / 7.0
exog = np.column_stack((np.ones(40), x, 2.0 * x))

# Try to find and use the correct matrix_rank function
try:
    from statsmodels.tools.linalg import matrix_rank
except ImportError:
    try:
        from numpy.linalg import matrix_rank
    except ImportError:
        from scipy.linalg import matrix_rank

# First scenario: matrix_rank(exog[:, list(cols)], method="qr") for cols in itertools.permutations(range(3))
try:
    results_qr = []
    for cols in itertools.permutations(range(3)):
        rank = matrix_rank(exog[:, list(cols)], method="qr")
        results_qr.append(rank)
    probe('matrix_rank(exog[:, list(cols)], method="qr") for cols in itertools.permutations(range(3)), where x = 1e3 * np.arange(1.0, 41.0) / 7.0 and exog = np.column_stack((np.ones(40), x, 2.0 * x))', results_qr)
except Exception as e:
    probe_exception('matrix_rank(exog[:, list(cols)], method="qr") for cols in itertools.permutations(range(3)), where x = 1e3 * np.arange(1.0, 41.0) / 7.0 and exog = np.column_stack((np.ones(40), x, 2.0 * x))', e)

# Second scenario: matrix_rank(exog[:, list(cols)], method=method) for each cols permutation of the 3-column exog, for method in ["ip", "qr", "svd"]
try:
    results_all_methods = {}
    for method in ["ip", "qr", "svd"]:
        method_results = []
        for cols in itertools.permutations(range(3)):
            rank = matrix_rank(exog[:, list(cols)], method=method)
            method_results.append(rank)
        results_all_methods[method] = method_results
    probe('matrix_rank(exog[:, list(cols)], method=method) for each cols permutation of the 3-column exog, for method in ["ip", "qr", "svd"]', results_all_methods)
except Exception as e:
    probe_exception('matrix_rank(exog[:, list(cols)], method=method) for each cols permutation of the 3-column exog, for method in ["ip", "qr", "svd"]', e)

